python -c from docx import Document
p='/mnt/data/望道-计算与智能创新学院-董锐麟-25803050309.docx'
d=Document(p)
for ti,table in enumerate(d.tables):
 for ri,row in enumerate(table.rows):
  for ci,cell in enumerate(row.cells):
   for pi,para in enumerate(cell.paragraphs):
    t=para.text.strip()
    if '关键词' in t or '课题的目的和意义' in t or '研究背景与问题提出' in t:
     pf=para.paragraph_format
     print('table',ti,'cell',ri,ci,'p',pi,repr(t))
     print('style',para.style.name,'keep_with_next',pf.keep_with_next,'keep_together',pf.keep_together,'page_break_before',pf.page_break_before,'widow_control',pf.widow_control)
     print(para._p.xml[:1800])
